module.exports = function(RED) {
    "use strict";

    const {execFile} = require("child_process");
    const {promisify} = require("util");
    const createGitRepositoryService = require("./lib/git-repos");
    const run = promisify(execFile);
    const pendingSwitches = new Map();
    const {listRepositories, listBranches, resolveRepository} = createGitRepositoryService(RED.settings);

    async function git(directory, args) {
        const result = await run("git", args, {
            cwd: directory,
            timeout: 5000,
            maxBuffer: 1024 * 1024,
            windowsHide: true,
            env: Object.assign({}, process.env, {GIT_OPTIONAL_LOCKS: "0", GIT_NO_LAZY_FETCH: "1"})
        });
        return result.stdout.trim();
    }

    async function switchBranch(directory, args) {
        const result = await run("git", args, {
            cwd: directory,
            timeout: 30000,
            maxBuffer: 1024 * 1024,
            windowsHide: true,
            env: Object.assign({}, process.env, {GIT_NO_LAZY_FETCH: "1"})
        });
        return result.stdout.trim();
    }

    async function fetchRemotes(directory) {
        const result = await run("git", ["fetch", "--all", "--prune"], {
            cwd: directory,
            timeout: 120000,
            maxBuffer: 1024 * 1024,
            windowsHide: true,
            env: Object.assign({}, process.env, {GIT_TERMINAL_PROMPT: "0"})
        });
        return result.stdout.trim();
    }

    async function withRepositoryLock(directory, action) {
        const previous = pendingSwitches.get(directory) || Promise.resolve();
        let release;
        const current = new Promise(resolve => { release = resolve; });
        pendingSwitches.set(directory, current);
        await previous;
        try {
            return await action();
        } finally {
            release();
            if (pendingSwitches.get(directory) === current) {
                pendingSwitches.delete(directory);
            }
        }
    }

    async function checkoutBranch(repository, requestedBranch, fetchRemote, pullLatest) {
        return withRepositoryLock(repository.path, async function() {
            if (fetchRemote || pullLatest) {
                await fetchRemotes(repository.path);
            }
            const branches = await listBranches(repository.path);
            const selected = branches.find(branch => branch.ref === requestedBranch) ||
                branches.find(branch => !branch.remote && branch.name === requestedBranch) ||
                branches.find(branch => branch.remote && branch.name === requestedBranch);
            if (!selected) {
                throw new Error("Selected Git branch is not available");
            }
            const localName = selected.remote ? selected.name.slice(selected.name.indexOf("/") + 1) : selected.name;
            if (!localName || localName.startsWith("-")) {
                throw new Error("Invalid branch name");
            }
            const localRef = "refs/heads/" + localName;
            const existingLocal = selected.remote && branches.some(branch => branch.ref === localRef);
            if (existingLocal) {
                const upstream = await git(repository.path, ["for-each-ref", "--format=%(upstream)", localRef]);
                if (upstream !== selected.ref) {
                    throw new Error("A local branch with a different upstream already exists; select it explicitly");
                }
            }
            const upstream = pullLatest ? (selected.remote ? selected.ref :
                await git(repository.path, ["for-each-ref", "--format=%(upstream)", localRef])) : null;
            if (pullLatest && !upstream) {
                throw new Error("Selected branch has no upstream to pull from");
            }
            let currentRef;
            try {
                currentRef = await git(repository.path, ["symbolic-ref", "--quiet", "HEAD"]);
            } catch (error) {
                if (error.code !== 1) {
                    throw error;
                }
            }
            if (currentRef !== localRef || pullLatest) {
                if (await git(repository.path, ["status", "--porcelain=v1", "--untracked-files=all"])) {
                    throw new Error("Repository has uncommitted changes; commit or stash them before switching branches");
                }
            }
            if (currentRef !== localRef) {
                if (selected.remote && !existingLocal) {
                    await switchBranch(repository.path, ["switch", "--track", "--create", localName, selected.name]);
                } else {
                    await switchBranch(repository.path, ["switch", localName]);
                }
            }
            if (pullLatest) {
                await switchBranch(repository.path, ["merge", "--ff-only", upstream]);
            }
            const ref = await git(repository.path, ["symbolic-ref", "--quiet", "HEAD"]);
            return {
                repository: repository.name,
                branch: ref.slice("refs/heads/".length),
                ref,
                path: repository.path
            };
        });
    }

    function GitRepoNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        node.on("input", async function(msg, send, done) {
            try {
                const payload = msg.payload;
                const dynamic = payload !== null && typeof payload === "object" && !Array.isArray(payload);
                const hasRepository = dynamic && Object.prototype.hasOwnProperty.call(payload, "repository");
                const hasBranch = dynamic && Object.prototype.hasOwnProperty.call(payload, "branch");
                if (hasRepository !== hasBranch) {
                    throw new Error("Provide both msg.payload.repository and msg.payload.branch");
                }
                const repositoryName = hasRepository ? payload.repository : config.repository;
                const requestedBranch = hasBranch ? payload.branch : config.branch;
                if (typeof requestedBranch !== "string" || !requestedBranch) {
                    throw new Error("A Git branch is required");
                }
                const repository = await resolveRepository(repositoryName);
                msg.git = await checkoutBranch(repository, requestedBranch, config.fetchRemote === true, config.pullLatest === true);
                node.status({});
                send(msg);
                done();
            } catch (error) {
                node.status({fill: "red", shape: "ring", text: error.message});
                done(error);
            }
        });
    }

    RED.httpAdmin.get("/git-repos", RED.auth.needsPermission("git-repos.read"), async function(req, res) {
        try {
            res.json((await listRepositories()).map(repository => repository.name));
        } catch (error) {
            res.status(503).json({error: "Git repository list is unavailable"});
        }
    });

    RED.httpAdmin.get("/git-repos/:repository/branches", RED.auth.needsPermission("git-repos.read"), async function(req, res) {
        try {
            const repository = await resolveRepository(req.params.repository);
            res.json(await listBranches(repository.path));
        } catch (error) {
            res.status(404).json({error: "Git repository is unavailable"});
        }
    });

    RED.nodes.registerType("git repo", GitRepoNode);
};
